'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var tape = require( 'tape' );
var NINF = require( '@stdlib/constants/float32/ninf' );
var PINF = require( '@stdlib/constants/float32/pinf' );
var isnan = require( '@stdlib/math/base/assert/is-nan' );
var isNegativeZero = require( '@stdlib/math/base/assert/is-negative-zero' );
var isPositiveZero = require( '@stdlib/math/base/assert/is-positive-zero' );
var tryRequire = require( '@stdlib/utils/try-require' );
var toFloat32 = require( '@stdlib/number/float64/base/to-float32' );


// VARIABLES //

var round10f = tryRequire( resolve( __dirname, './../lib/native.js' ) );
var opts = {
	'skip': ( round10f instanceof Error )
};


// TESTS //

tape( 'main export is a function', opts, function test( t ) {
	t.ok( true, __filename );
	t.strictEqual( typeof round10f, 'function', 'main export is a function' );
	t.end();
});

tape( 'returns +0 if +0', opts, function test( t ) {
	var v = round10f( toFloat32( +0.0 ) );
	t.strictEqual( isPositiveZero( v ), true );
	t.end();
});

tape( 'returns -0 if -0', opts, function test( t ) {
	var v = round10f( toFloat32( -0.0 ) );
	t.strictEqual( isNegativeZero( v ), true );
	t.end();
});

tape( 'returns NaN if NaN', opts, function test( t ) {
	var v = round10f( NaN );
	t.strictEqual( isnan( v ), true );
	t.end();
});

tape( 'returns +inf if +inf', opts, function test( t ) {
	var v = round10f( PINF );
	t.strictEqual( v, PINF );
	t.end();
});

tape( 'returns -inf if -inf', opts, function test( t ) {
	var v = round10f( NINF );
	t.strictEqual( v, NINF );
	t.end();
});

tape( 'rounds to nearest power of 10', opts, function test( t ) {
	t.strictEqual( round10f( toFloat32( -4.2 ) ), toFloat32( -1.0 ) );
	t.strictEqual( round10f( toFloat32( 9.4 ) ), toFloat32( 10.0 ) );
	t.strictEqual( round10f( toFloat32( 60.1 ) ), toFloat32( 100.0 ) );
	t.strictEqual( round10f( toFloat32( 0.3 ) ), toFloat32( 0.1 ) );
	t.end();
});
